 42→    setDeleteError(null);
 43→    try {
 44→      await authApi.deleteAccount();
 45→      // Account deleted server-side. Clear local state and redirect.
 46→      await logout();
 47→    } catch (err) {
 48→      setDeleteError(err instanceof Error ? err.message : 'Failed to delete account');
 49→      setIsDeleting(false);
 50→    }
