 65→          aria-hidden="true"
 66→        />
 67→        <span className={`security-tab-status-label ${isMfaEnabled ? 'enabled' : 'disabled'}`}>
 68→          {isMfaEnabled ? '[ENABLED]' : '[DISABLED]'}
