    it('should use identifierHash for duplicate check', async () => {
      const mockUser = { id: 'user-id', publicKey: 'pub-key' };
      const mockPayload = { sub: 'user-123', email: 'user@example.com' };
      const identifierHash = sha256Hex('user@example.com');
